"""Generated regression checks for the alternative crop recommendation project.
These tests exercise independent input combinations and keep the validation contract stable.
"""
import pytest
from src.data_validation import validate_sample, validate_frame
from src.recommend import recommend
from src.config import FEATURES
import pandas as pd

BUNDLE = None
BASE_SAMPLE = {
    "nitrogen": 55, "phosphorus": 45, "potassium": 40,
    "temperature": 26, "humidity": 65, "ph": 6.5, "rainfall": 70,
    "soil_type": "loamy", "season": "kharif", "region_zone": "sub_humid"
}

def test_generated_case_0000():
    sample = dict(BASE_SAMPLE, nitrogen=0, phosphorus=0, potassium=0, temperature=-5.0, humidity=0.0, ph=3.0, rainfall=0.0, soil_type='loamy', season='kharif', region_zone='arid')
    normalized = validate_sample(sample)
    assert set(FEATURES).issubset(normalized)
    assert 0 <= normalized['nitrogen'] <= 140
    assert 0 <= normalized['phosphorus'] <= 145
    assert 0 <= normalized['potassium'] <= 210
    assert 0 <= normalized['humidity'] <= 100
    assert 3 <= normalized['ph'] <= 10
    assert 0 <= normalized['rainfall'] <= 400

